    s << indent << "gear_command: ";
    s << std::endl;
    Printer< ::planning_msgs::GearCommand_<ContainerAllocator> >::stream(s, indent + "  ", v.gear_command);
    s << indent << "vehicle_lock_command: ";
    s << std::endl;
    Printer< ::planning_msgs::VehicleLockCommand_<ContainerAllocator> >::stream(s, indent + "  ", v.vehicle_lock_command);
    s << indent << "plan_status: ";
